static String text(const char* pt,const char* en,const char* es){const auto l=SystemStats::getUserLanguage();return String::fromUTF8(l.startsWithIgnoreCase("pt")?pt:l.startsWithIgnoreCase("es")?es:en);}
class Timeline final : public Component {
public:
    Array<var> peaks,regions;StringArray names;double duration=0,position=0,bpm=120,zoom=1,start=0;int meter=4,selected=-1;bool playing=false,looping=false;
    std::function<void(double)> onSeek;std::function<void(int)> onRegion;
    void reset(){start=0;zoom=1;selected=-1;repaint();}
    void setZoom(double value){double anchor=start+duration/zoom*.5;zoom=jlimit(1.,24.,value);start=jlimit(0.,jmax(0.,duration-duration/zoom),anchor-duration/zoom*.5);manualUntil=Time::getMillisecondCounterHiRes()+4000;repaint();}
    void follow(){if(playing&&Time::getMillisecondCounterHiRes()>manualUntil){double visible=duration/zoom;if(position<start||position>start+visible*.85)start=jlimit(0.,jmax(0.,duration-visible),position-visible*.12);}}
    void paint(Graphics& g)override{
        auto r=getLocalBounds().toFloat();g.setColour(performance::background);g.fillRoundedRectangle(r,7);if(duration<=0||peaks.isEmpty()){g.setColour(performance::muted);g.setFont(FontOptions(15.f));g.drawFittedText(text("Abra um projeto para começar","Open a project to begin","Abre un proyecto para empezar"),getLocalBounds(),Justification::centred,2);return;}
        follow();auto xFor=[&](double t){return float((t-start)/duration*getWidth()*zoom);};float top=31,bottom=jmax(top+10,float(getHeight()-22)),center=top+(bottom-top)*.54f;float height=(bottom-top-22)*.44f;
        Array<float> envelope;float maximum=.001f;int bins=0;for(const auto& row:peaks)bins=jmax(bins,row.size());for(int i=0;i<bins;++i){float value=0;for(const auto& row:peaks)if(i<row.size())value=jmax(value,float(double(row[i])));envelope.add(value);maximum=jmax(maximum,value);}Path wave;int steps=jmax(2,getWidth()*2);for(int i=0;i<=steps;++i){double t=start+duration/zoom*i/steps;int index=jlimit(0,bins-1,int(t/duration*bins));float amplitude=envelope[index]/jmax(.08f,maximum)*height;float x=float(getWidth())*i/steps;if(i==0)wave.startNewSubPath(x,center-amplitude);else wave.lineTo(x,center-amplitude);}for(int i=steps;i>=0;--i){double t=start+duration/zoom*i/steps;int index=jlimit(0,bins-1,int(t/duration*bins));wave.lineTo(float(getWidth())*i/steps,center+envelope[index]/jmax(.08f,maximum)*height);}wave.closeSubPath();
        double beat=60./jmax(20.,bpm);int stride=1;while(beat/duration*getWidth()*zoom*stride<18)stride*=2;
        auto drawRegion=[&](double from,double to,String title,Colour colour,int index){auto box=Rectangle<float>(xFor(from)+1,top,jmax(1.f,xFor(to)-xFor(from)-2),bottom-top);if(box.getRight()<0||box.getX()>getWidth())return;Graphics::ScopedSaveState saved(g);g.reduceClipRegion(box.toNearestInt());g.setGradientFill(ColourGradient(performance::background.interpolatedWith(colour,.16f),box.getX(),top,performance::background.interpolatedWith(colour,.24f),box.getRight(),bottom,false));g.fillRoundedRectangle(box,7);g.setGradientFill(ColourGradient(colour,0,top,colour.brighter(.2f),0,bottom,false));g.fillPath(wave);for(double t=std::ceil(start/beat/stride)*beat*stride;t<=jmin(duration,start+duration/zoom);t+=beat*stride){g.setColour(Colours::white.withAlpha(.10f));g.drawVerticalLine(roundToInt(xFor(t)),top+24,bottom);}g.setColour(colour);g.drawRoundedRectangle(box,7,.8f);bool active=playing&&position>=from&&position<to;if(active||index==selected){g.setColour(looping&&index==selected?Colour(0xffe8bd59):performance::cyan);g.drawRoundedRectangle(box.reduced(.7f),7,1.6f);}g.setColour(performance::ink);g.setFont(FontOptions(11.f));g.drawFittedText(title,Rectangle<int>(roundToInt(box.getX()+8),roundToInt(top+4),jmax(1,roundToInt(box.getWidth()-16)),18),Justification::centredLeft,1);};
        if(regions.isEmpty())drawRegion(0,duration,{},Colour(0xff41a4d8),-1);else{drawRegion(0,duration,{},Colour(0xff314054),-1);int i=0;for(const auto& region:regions){auto colour=Colour::fromString(region["color"].toString().replace("#","ff"));if(region["color"].toString().isEmpty())colour=Colour::fromHSV(float(i%5)*.13f+.08f,.62f,.87f,1.f);drawRegion(double(region["start"]),double(region["end"]),region["name"].toString(),colour,i++);}}
        g.setColour(Colour(0xff425168));g.drawHorizontalLine(27,0,float(getWidth()));g.setFont(FontOptions(10.f));for(double t=std::ceil(start/beat/stride)*beat*stride;t<=jmin(duration,start+duration/zoom);t+=beat*stride){float x=xFor(t);g.setColour(performance::muted);g.drawVerticalLine(roundToInt(x),21,27);if(int(std::round(t/beat))%jmax(1,meter)==0)g.drawText(String(int(t/beat)/jmax(1,meter)+1),int(x)+3,4,40,17,Justification::centredLeft);}
        g.setColour(performance::muted);g.drawText(String(roundToInt(zoom*100))+"%",getWidth()-100,3,44,18,Justification::centredRight);g.setFont(FontOptions(10.f));for(int i=0;i<5;++i){double t=start+duration/zoom*i/4;g.drawText(String(int(t)/60)+":"+String(int(t)%60).paddedLeft('0',2),getWidth()*i/4-20,getHeight()-18,45,16,Justification::centred);}
        float cursor=xFor(position);g.setColour(Colours::white.withAlpha(.18f));g.fillRect(cursor-2,26.f,4.f,bottom-26);g.setColour(Colours::white);g.drawVerticalLine(roundToInt(cursor),26,bottom);g.fillEllipse(cursor-3,23,6,6);
    }
    void mouseDown(const MouseEvent& e)override{down=e.position;downStart=start;moved=false;cursorDrag=!playing&&duration>0&&std::abs(e.position.x-float((position-start)/duration*getWidth()*zoom))<18;}
    void mouseDrag(const MouseEvent& e)override{if(e.position.getDistanceFrom(down)>5)moved=true;if(cursorDrag&&moved&&onSeek){onSeek(jlimit(0.,duration,start+e.position.x/jmax(1,getWidth())*duration/zoom));return;}if(zoom>1&&moved){start=jlimit(0.,jmax(0.,duration-duration/zoom),downStart-(e.position.x-down.x)/jmax(1,getWidth())*duration/zoom);manualUntil=Time::getMillisecondCounterHiRes()+4000;repaint();}}
    void mouseUp(const MouseEvent& e)override{if(duration<=0)return;if(!moved){double t=jlimit(0.,duration,start+e.position.x/jmax(1,getWidth())*duration/zoom);if(e.position.y>=31&&e.position.y<getHeight()-22)for(int i=0;i<regions.size();++i)if(t>=double(regions[i]["start"])&&t<double(regions[i]["end"])){selected=i;if(onRegion)onRegion(i);if(!playing&&onSeek)onSeek(double(regions[i]["start"]));repaint();return;}if(onSeek)onSeek(t);}}
private:Point<float> down;double downStart=0,manualUntil=0;bool moved=false,cursorDrag=false;
};
