    void load(const Array<File>& files){
        Array<var> requests;for(const auto& f:files)requests.add(json({{"token",f.getFileName()},{"path",f.getFullPathName()}}));auto metadata=send(json({{"op","probe"},{"files",requests}}));if(!metadata.isArray()||metadata.size()!=files.size())return;
        Array<var> next;double length=0;for(int i=0;i<files.size();++i){const double seconds=double(metadata[i]["duration"]);length=jmax(length,seconds);next.add(json({{"gain",1},{"pitch",0},{"bus","VS"},{"effectId","track:"+String(i)},{"items",Array<var>{json({{"path",files[i].getFullPathName()},{"position",0},{"offset",0},{"length",seconds},{"rate",1}})}}}));}
        loaded=false;deviceReady=false;auto state=send(json({{"op","load"},{"tracks",next},{"duration",length},{"sampleRate",44100},{"offline",true},{"master",master.getValue()}}));if(!state.isObject())return;
        setlist={};library.clear(dontSendNotification);projectMeter=4;timeline.regions.clear();tracks=next;duration=length;loaded=true;playing=false;seek.setRange(0,jmax(.01,duration),.01);channels.clear();names.clear();faders.clear();
        for(int i=0;i<files.size();++i){auto* fader=faders.add(new Slider());fader->setRange(0,2,.01);fader->setValue(1);fader->setName(files[i].getFileNameWithoutExtension());tracks.getReference(i).getDynamicObject()->setProperty("pitchEnabled",true);addChannel(*fader,files[i].getFileNameWithoutExtension(),i);}originalKey.clear();targetKey.clear();refreshKeys();timeline.reset();loop.setToggleState(false,dontSendNotification);timeline.looping=false;
        timeline.names.clear();timeline.peaks.clear();for(const auto& file:files){timeline.names.add(file.getFileNameWithoutExtension());timeline.peaks.add(send(json({{"op","peaks"},{"path",file.getFullPathName()},{"bins",256}})));}timeline.duration=duration;timeline.position=0;timeline.repaint();song.setText(files.size()==1?files[0].getFileNameWithoutExtension():text("Áudios importados","Imported audio","Audios importados")+" ("+String(files.size())+")",dontSendNotification);
        currentSong=song.getText();rebuildCards();enableTransport(true);status.setText(text("Áudio importado. Toque para iniciar.","Audio imported. Press Play to start.","Audio importado. Pulsa Reproducir."),dontSendNotification);resized();updateMix();
    }
    void timerCallback()override{
        auto area=safeBounds();if(area!=lastSafeArea){lastSafeArea=area;resized();}
        tap.setToggleState(Time::getMillisecondCounterHiRes()<tapUntil,dontSendNotification);if(!loaded||importing)return;auto state=send(json({{"op","status"}}));if(!state.isObject())return;playing=bool(state["playing"]);play.setButtonText(playing?text("Pausar","Pause","Pausar"):text("Tocar","Play","Reproducir"));play.setToggleState(playing,dontSendNotification);timeline.position=double(state["position"]);timeline.playing=playing;timeline.bpm=bpm.getValue();timeline.meter=projectMeter;timeline.repaint();if(!seek.isMouseButtonDown())seek.setValue(double(state["position"]),dontSendNotification);clock.setText(clockText(double(state["position"]))+" / "+clockText(duration),dontSendNotification);auto meters=send(json({{"op","meters"}}));for(int i=0;i<channels.size();++i){auto values=meters[Identifier("track:"+String(i))];channels[i]->level=float(jmax(double(values[0]),double(values[1])));channels[i]->repaint();}auto masterValues=meters["master"],clickValues=meters["click"];masterChannel->level=float(jmax(double(masterValues[0]),double(masterValues[1])));clickChannel->level=float(jmax(double(clickValues[0]),double(clickValues[1])));masterChannel->repaint();clickChannel->repaint();
        auto events=send(json({{"op","events"}}));if(events.isArray()&&!events.getArray()->isEmpty())status.setText(text("A reprodução encontrou um erro de áudio.","Playback encountered an audio error.","La reproducción encontró un error de audio."),dontSendNotification);
    }
